import os, shutil

os.makedirs("constant/triSurface", exist_ok=True)
os.makedirs("system", exist_ok=True)
shutil.copy("sphere.stl", "constant/triSurface/sphere.stl")

controlDict = r"""
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
application     simpleFoam;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1;
deltaT          1;
writeControl    timeStep;
writeInterval   1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
"""
with open("system/controlDict", "w") as f:
    f.write(controlDict)

fvSchemes = r"""
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
"""
with open("system/fvSchemes", "w") as f:
    f.write(fvSchemes)

fvSolution = r"""
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSolution;
}
solvers {}
"""
with open("system/fvSolution", "w") as f:
    f.write(fvSolution)

print(os.listdir("system"))
print(os.listdir("constant/triSurface"))

import subprocess

D_M = 0.040
UPSTREAM_M   = 5 * D_M   # 0.20 m
DOWNSTREAM_M = 15 * D_M  # 0.60 m
SIDE_M       = 5 * D_M   # 0.20 m  (y and z half-extent)

XMIN, XMAX = -UPSTREAM_M, DOWNSTREAM_M
YMIN, YMAX = -SIDE_M, SIDE_M
ZMIN, ZMAX = -SIDE_M, SIDE_M

# Coarse background cell size for the first look: one cell per diameter.
CELL_M = D_M
NX = round((XMAX - XMIN) / CELL_M)
NY = round((YMAX - YMIN) / CELL_M)
NZ = round((ZMAX - ZMIN) / CELL_M)
print("domain:", XMIN, XMAX, YMIN, YMAX, ZMIN, ZMAX)
print("background cells:", NX, NY, NZ, "total:", NX*NY*NZ)

blockMeshDict = f"""
FoamFile
{{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      blockMeshDict;
}}

scale 1;

vertices
(
    ({XMIN} {YMIN} {ZMIN})
    ({XMAX} {YMIN} {ZMIN})
    ({XMAX} {YMAX} {ZMIN})
    ({XMIN} {YMAX} {ZMIN})
    ({XMIN} {YMIN} {ZMAX})
    ({XMAX} {YMIN} {ZMAX})
    ({XMAX} {YMAX} {ZMAX})
    ({XMIN} {YMAX} {ZMAX})
);

blocks
(
    hex (0 1 2 3 4 5 6 7) ({NX} {NY} {NZ}) simpleGrading (1 1 1)
);

edges ();

boundary
(
    inlet
    {{
        type patch;
        faces
        (
            (0 4 7 3)
        );
    }}
    outlet
    {{
        type patch;
        faces
        (
            (1 2 6 5)
        );
    }}
    farField
    {{
        type patch;
        faces
        (
            (0 1 5 4)
            (3 7 6 2)
            (0 3 2 1)
            (4 5 6 7)
        );
    }}
);

mergePatchPairs ();
"""
with open("system/blockMeshDict", "w") as f:
    f.write(blockMeshDict)

print(subprocess.run(["blockMesh"], capture_output=True, text=True).stdout[-3000:])

import subprocess

D_M = 0.040
R_M = D_M / 2.0

# location well downstream of the sphere, inside the fluid domain, far from any surface
LOC_IN_MESH = (0.30, 0.0, 0.0)
dist_from_sphere_centre = (LOC_IN_MESH[0]**2 + LOC_IN_MESH[1]**2 + LOC_IN_MESH[2]**2) ** 0.5
print("locationInMesh:", LOC_IN_MESH, " distance from sphere centre:", dist_from_sphere_centre, " sphere radius:", R_M)
assert dist_from_sphere_centre > R_M, "seed point must be outside the sphere"

snappyHexMeshDict = f"""
FoamFile
{{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      snappyHexMeshDict;
}}

castellatedMesh true;
snap            true;
addLayers       true;

geometry
{{
    sphere.stl
    {{
        type triSurfaceMesh;
        name sphere;
    }}
}};

castellatedMeshControls
{{
    maxLocalCells       200000;
    maxGlobalCells      2000000;
    minRefinementCells   0;
    maxLoadUnbalance     0.10;
    nCellsBetweenLevels  3;

    features ();

    refinementSurfaces
    {{
        sphere
        {{
            level (1 1);
            patchInfo {{ type wall; }}
        }}
    }}

    resolveFeatureAngle 30;

    refinementRegions {{}}

    locationInMesh ({LOC_IN_MESH[0]} {LOC_IN_MESH[1]} {LOC_IN_MESH[2]});
    allowFreeStandingZoneFaces true;
}}

snapControls
{{
    nSmoothPatch     3;
    tolerance        2.0;
    nSolveIter       30;
    nRelaxIter       5;
    nFeatureSnapIter 10;
}}

addLayersControls
{{
    relativeSizes true;
    layers
    {{
        sphere
        {{
            nSurfaceLayers 4;
        }}
    }}
    expansionRatio        1.2;
    finalLayerThickness   0.3;
    minThickness          0.1;
    nGrow                 0;
    featureAngle          60;
    nRelaxIter            5;
    nSmoothSurfaceNormals 1;
    nSmoothNormals        3;
    nSmoothThickness      10;
    maxFaceThicknessRatio 0.5;
    maxThicknessToMedialRatio 0.3;
    minMedianAxisAngle    90;
    nBufferCellsNoExtrude 0;
    nLayerIter            50;
}}

meshQualityControls
{{
    maxNonOrtho 65;
    maxBoundarySkewness 20;
    maxInternalSkewness 4;
    maxConcave 80;
    minVol 1e-13;
    minTetQuality -1e30;
    minArea -1;
    minTwist 0.02;
    minDeterminant 0.001;
    minFaceWeight 0.05;
    minVolRatio 0.01;
    minTriangleTwist -1;
    nSmoothScale 4;
    errorReduction 0.75;
}}

debug 0;
mergeTolerance 1e-6;
"""
with open("system/snappyHexMeshDict", "w") as f:
    f.write(snappyHexMeshDict)

print("wrote snappyHexMeshDict")
